import{_ as a,C as d,o as i,c as r,E as o,a2 as l}from"./chunks/framework.BOeh4kYD.js";const _=JSON.parse('{"title":"工具能接上，不等于能力可复用","description":"","frontmatter":{"title":"工具能接上，不等于能力可复用","date":"2026-09-09","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当智能体或数字员工把多个工具组合成可复用能力图时，什么证据足以把输出到输入的绑定视为可操作能力，而成功执行仍然不能证明什么？","summary":"工具的输出字段与下一个工具的输入参数看起来兼容，只能形成候选连接。KOPA-Bench（韩国开放公共应用程序接口基准）与 EDGE（执行驱动图演化方法）的研究表明，实时执行、集合处理语义、失败分类和证据新鲜度都会改变这条连接是否值得复用；而具备能力仍不等于本次获得授权。","sources":["research/analysis/Q-20260909-01-execution-grounded-capability-evidence.md"],"item_id":"Q-20260909-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-09-tool-edge-needs-execution-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-09-tool-edge-needs-execution-evidence.md","filePath":"zh/digital-employee/2026-09-09-tool-edge-needs-execution-evidence.md","lastUpdated":1788955869000}'),n={name:"zh/digital-employee/2026-09-09-tool-edge-needs-execution-evidence.md"};function s(p,e,c,h,u,m){const t=d("ArticleCover");return i(),r("div",null,[o(t,{image:"/assets/covers/daily-2026-09-09-tool-edge-needs-execution-evidence-cover.png",kicker:"数字员工 · 每日研究",title:"工具能接上，不等于能力可复用",summary:"工具的输出字段与下一个工具的输入参数看起来兼容，只能形成候选连接。KOPA-Bench（韩国开放公共应用程序接口基准）与 EDGE（执行驱动图演化方法）的研究表明，实时执行、集合处理语义、失败分类和证据新鲜度都会改变这条连接是否值得复用；而具备能力仍不等于本次获得授权。",version:"Q-20260909-01",status:"Daily Runtime V5 · 2026-09-09",languageHref:"/en/digital-employee/2026-09-09-tool-edge-needs-execution-evidence",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="工具能接上-不等于能力可复用" tabindex="-1">工具能接上，不等于能力可复用 <a class="header-anchor" href="#工具能接上-不等于能力可复用" aria-label="Permalink to &quot;工具能接上，不等于能力可复用&quot;">​</a></h1><p>一个数字员工先调用检索工具，拿到一批企业；再把输出交给详情工具，最后写入客户系统。接口说明里的字段名称能够对上，模型也判断这条链“可行”。系统于是把它保存成可复用能力。</p><p>真正执行时，第一步返回的不是一个企业，而是 27 个；第二步只接受一个标识。运行体如果取第一条、遍历全部、先筛选再传递，得到的是三种不同业务效果。更麻烦的是，一次调用成功并不能说明下周升级后的接口、另一个租户的权限环境或新的默认参数仍然成立。</p><p>这类问题的核心不是“模型会不会挑工具”，而是：<strong>一条候选连接要凭什么晋升为正式能力，又应在什么变化后失效。</strong></p><p>本文的判断是：<strong>可复用工具组合应由版本化、执行落地、带出处且可刷新失效的证据准入；组合语义属于能力身份的一部分。能力证据说明“它在什么条件下能工作”，却不能代替“这一次是否允许执行”。</strong></p><h2 id="看起来能连接-只是候选关系" tabindex="-1">看起来能连接，只是候选关系 <a class="header-anchor" href="#看起来能连接-只是候选关系" aria-label="Permalink to &quot;看起来能连接，只是候选关系&quot;">​</a></h2><p>工具描述、输入输出模式和模型判断很有价值。它们能从上千个工具中缩小搜索空间，提出“这个输出也许可以成为那个输入”的假设。但假设不是已经投入运行的能力。</p><p>同日研究对象分析的 KOPA-Bench 与 EDGE 研究包含 145 个专家任务、2,318 个通过模型上下文协议（MCP）暴露的公共应用程序接口工具，以及一个会随执行证据变化的依赖图。研究机制先通过检索和模型可行性判断建立初始骨架，再利用真实调用的成功与失败更新边的置信度。</p><p>这一设计本身给出了重要边界：初始图里的边不需要先成功一次，因此它们代表“值得试验的候选”；执行后的图则多了一层观察证据，但仍不是跨版本、跨租户、跨时间永久有效的真理。</p><p>把这两个状态压成同一个“已支持”，会让系统失去最关键的治理信息：我们究竟只看见了结构上的可能性，还是已经观察到特定条件下的可重复行为。</p><h2 id="执行结果会改变证据" tabindex="-1">执行结果会改变证据 <a class="header-anchor" href="#执行结果会改变证据" aria-label="Permalink to &quot;执行结果会改变证据&quot;">​</a></h2><p>研究报告，模型判断形成的初始骨架执行成功率为 50.2%，收敛后的图达到 62.7%；后来被剪除的边，执行成功率只有 14.8%。这些数字不能证明某一种更新算法适用于所有企业系统，却足以说明一个更窄的事实：<strong>接口描述和模型判断没有包含全部运行信息，实时执行能够推翻看起来很强的先验。</strong></p><p>失败也不能一概而论。字段含义不匹配、必要参数无法构造，通常指向结构性问题；超时、限流或授权错误可能来自环境。若运行体把两类失败都写成“能力不存在”，就会过早删除可恢复连接；若全部写成“临时错误”，又会让真正错误的边反复进入生产。</p><p>因此，证据不应只有成功次数。它还需要记录失败类别、判定依据和未决状态。提供方返回模糊错误时，系统可以保留“原因未知”，而不是强行给出一个方便但虚假的布尔结论。</p><h2 id="组合语义属于能力身份" tabindex="-1">组合语义属于能力身份 <a class="header-anchor" href="#组合语义属于能力身份" aria-label="Permalink to &quot;组合语义属于能力身份&quot;">​</a></h2><p>研究中 81.2% 的链式调用消费多记录输出，中位基数为 27，最大达到 224,958。这个结果提醒我们，字段类型相容只是最外层条件。集合如何进入下一步，直接改变业务含义和副作用规模。</p><p>至少要区分三种组合方式：</p><ul><li>顺序传递：一次只传递一条记录，保持原顺序逐项执行；</li><li>扇出：对集合中的多条记录并行或批量调用下游工具；</li><li>确定性归约：先依据明确规则筛选、聚合或选定一条，再继续执行。</li></ul><p>它们可能使用同一输出字段和同一输入参数，却不是同一个能力。扇出会放大调用量与外部效果；归约规则会决定谁被保留；顺序处理会影响超时、恢复和部分完成。</p><p>所以，能力身份不能只写成“上游工具连接下游工具”。它还要包含集合基数、选择规则、默认值、变换逻辑、分支条件以及部分失败的处理方式。否则，所谓复用只是复用了接口外壳，没有复用经过验证的业务语义。</p><h2 id="能力证据包必须绑定什么" tabindex="-1">能力证据包必须绑定什么 <a class="header-anchor" href="#能力证据包必须绑定什么" aria-label="Permalink to &quot;能力证据包必须绑定什么&quot;">​</a></h2><p>一个最小的可审计证据包，可以保存以下事实：</p><table tabindex="0"><thead><tr><th>证据部分</th><th>需要绑定的内容</th><th>解决的问题</th></tr></thead><tbody><tr><td>工具身份</td><td>来源与目标工具、版本、端点</td><td>证明测试的是哪一组实现</td></tr><tr><td>字段与参数</td><td>输出字段、输入参数、默认值</td><td>说明数据怎样进入下一步</td></tr><tr><td>组合语义</td><td>基数、顺序、扇出、归约与分支</td><td>保留业务意义和效果规模</td></tr><tr><td>执行历史</td><td>试验次数、成功与失败、样本条件</td><td>说明置信度来自什么观察</td></tr><tr><td>失败分类</td><td>结构、环境或未知及其依据</td><td>避免错误剪枝和无限重试</td></tr><tr><td>环境出处</td><td>租户、凭据类别、服务状态、时间</td><td>限定证据适用范围</td></tr><tr><td>新鲜度规则</td><td>到期时间与变化触发条件</td><td>防止旧证据永久冒充现状</td></tr></tbody></table><p>证据可以分级，而不必追求一个全球统一阈值。低风险只读查询可能允许较少试验；不可逆写入或大规模扇出则需要更强的重复性、沙箱验证和效果约束。关键不是所有能力使用同一分数，而是准入决定能够回指同一份可复核事实。</p><h2 id="能力证明不是执行授权" tabindex="-1">能力证明不是执行授权 <a class="header-anchor" href="#能力证明不是执行授权" aria-label="Permalink to &quot;能力证明不是执行授权&quot;">​</a></h2><p>一条边在昨天、某个租户、某个工具版本下成功，说明它具备上下文限定的能力证据。它没有回答今天的数字员工是否可以访问目标账户、是否可以写入这些记录、是否应在当前业务请求中扇出 27 次。</p><p>能力准入与调用时授权需要分账：</p><ul><li>能力证据回答“这条组合在已观察条件下能否工作”；</li><li>授权证据回答“当前责任主体能否对当前目标产生预期效果”；</li><li>幂等证据回答“重试是否会复用原效果”；</li><li>事务证据回答“外部状态是否真正提交”；</li><li>恢复权限回答“出现未知效果后谁可以继续”。</li></ul><p>它们可以在一次执行中相互引用，但不能相互替代。尤其不能把“执行成功过”解释成永久权限，也不能把一次授权解释成能力已经得到充分验证。</p><h2 id="一次成功太少-永久有效太久" tabindex="-1">一次成功太少，永久有效太久 <a class="header-anchor" href="#一次成功太少-永久有效太久" aria-label="Permalink to &quot;一次成功太少，永久有效太久&quot;">​</a></h2><p>反对意见会说：如果每条工具边都要积累大量试验，能力图就无法快速扩展。这个担忧成立，因此候选状态有必要存在。系统可以允许探索性执行，在受限目标、可逆环境和较小效果范围内收集证据，而不是要求能力在第一次使用前就达到最终置信度。</p><p>但“一次成功即永久注册”走向了另一个极端。一次成功可能只覆盖一个参数形状、一条记录、一个时间窗口。工具升级、模式变化、端点迁移、凭据上下文改变，或者近期失败率显著变化，都应让证据降级或触发重新验证。</p><p>最合理的模型不是“有能力/没能力”两个永久状态，而是候选、受限准入、已准入、证据过期和已撤销等可追踪状态。历史成功仍然保留为事实，但不再自动支撑当前激活。</p><h2 id="证据边界与开放问题" tabindex="-1">证据边界与开放问题 <a class="header-anchor" href="#证据边界与开放问题" aria-label="Permalink to &quot;证据边界与开放问题&quot;">​</a></h2><p>KOPA-Bench 的实证范围是韩国公共部门接口，公开仓库仍把部分语料、检查点和基准资产标为后续开放。它没有证明所有企业工具图都应采用同一贝叶斯更新规则，也没有覆盖大量不可逆事务、复杂租户权限与长期服务演化。</p><p>仍待回答的问题包括：不同风险等级需要多少次、什么分布的试验；跨租户证据能否迁移；提供方只返回模糊错误时怎样区分结构与环境故障；工具版本没有显式变化但行为漂移时怎样触发过期；能力置信度应如何影响规划，却不越权改变授权决定。</p><p>工程上可以先坚持一条底线：<strong>模式和模型判断可以提出能力候选，只有带身份、带语义、带执行历史并能够过期的证据，才能把它提升为可复用能力。</strong></p><p><strong>证据与引用：</strong></p><ul><li><a href="https://arxiv.org/html/2609.05395v1" target="_blank" rel="noreferrer">KOPA-Bench / EDGE 主研究</a></li></ul>',39))])}const b=a(n,[["render",s]]);export{_ as __pageData,b as default};
